import React, { useState } from 'react';
import './RecommendationCard.css';

const CATEGORY_COLORS = {
  supplier: '#4f8ef7',
  shipment: '#f59e0b',
  inventory: '#22c55e',
  'cross-functional': '#a855f7',
};

const PRIORITY_LABELS = { 1: 'Critical', 2: 'High', 3: 'Medium' };

export default function RecommendationCard({ recommendation, index }) {
  const [showScores, setShowScores] = useState(false);
  const { title, description, priority, category, evidence, judge_scores } = recommendation;
  const color = CATEGORY_COLORS[category] || '#94a3b8';
  const priorityLabel = PRIORITY_LABELS[priority] || `P${priority}`;

  return (
    <div className="rec-card" style={{ '--accent-color': color }}>
      <div className="rec-card__header">
        <div className="rec-card__meta">
          <span className="rec-priority" data-priority={priority}>
            {priorityLabel}
          </span>
          <span className="rec-category" style={{ color }}>
            {category}
          </span>
        </div>
        {judge_scores && (
          <button className="scores-toggle" onClick={() => setShowScores(v => !v)}>
            Score: {judge_scores.total ?? '—'}/15
          </button>
        )}
      </div>

      <h4 className="rec-card__title">{title}</h4>
      <p className="rec-card__description">{description}</p>

      {evidence && (
        <div className="rec-card__evidence">
          <span className="evidence-label">Evidence</span>
          <p>{evidence}</p>
        </div>
      )}

      {showScores && judge_scores && (
        <div className="rec-scores">
          <div className="score-row">
            <span>Actionability</span>
            <ScoreBar value={judge_scores.actionability} />
          </div>
          <div className="score-row">
            <span>Evidence Grounding</span>
            <ScoreBar value={judge_scores.evidence_grounding} />
          </div>
          <div className="score-row">
            <span>Specificity</span>
            <ScoreBar value={judge_scores.specificity} />
          </div>
          {judge_scores.rationale && (
            <p className="score-rationale">{judge_scores.rationale}</p>
          )}
        </div>
      )}
    </div>
  );
}

function ScoreBar({ value }) {
  const pct = ((value || 0) / 5) * 100;
  const color = pct >= 70 ? 'var(--success)' : pct >= 40 ? 'var(--warning)' : 'var(--danger)';
  return (
    <div className="score-bar-wrap">
      <div className="score-bar">
        <div className="score-bar__fill" style={{ width: `${pct}%`, background: color }} />
      </div>
      <span className="score-num">{value}/5</span>
    </div>
  );
}
